const daycounts = () => {
  // verify day counts used in session 1 (Oct 25, 2026 as-of date)
  const daysBetween = (a, b) => (new Date(b) - new Date(a)) / 86400000;
  return {
    "Apr30->Oct25": daysBetween("2026-04-30", "2026-10-25"),
    "May31->Oct25": daysBetween("2026-05-31", "2026-10-25"),
    "Jun30->Oct25": daysBetween("2026-06-30", "2026-10-25"),
    "Jul31->Oct25": daysBetween("2026-07-31", "2026-10-25"),
    "Aug31->Oct25": daysBetween("2026-08-31", "2026-10-25"),
    "Sep29->Oct25": daysBetween("2026-09-29", "2026-10-25"),
  };
};
const interest = (p, d) => p * 0.01 * (d / 30);
const i4411 = interest(68400, 178);
const i4452 = interest(71250, 147);
const i4490 = interest(66100, 117);
const i4533R = interest(71700, 86);
const i4571 = interest(59450, 55);
const i4533_orig = interest(74800, 86);
const four = i4411 + i4452 + i4490 + i4571;
const total = four + i4533R;
const fourInv = 68400 + 71250 + 66100 + 59450;
const j4533R = 74800 - 3100;
const conversions = 5 * 0.25 * 64000;
const principal = fourInv + j4533R + conversions;
const grand = principal + total;
const dailyAll = (fourInv + j4533R) * 0.01 / 30;
const dailyFour = fourInv * 0.01 / 30;
const session1Total = 433361.74;
const delta = session1Total - grand;
const forgoneInterest = i4533_orig - i4533R;
const vsCEO = 862000 - grand;
// reconciliation vs session 1
const recon = -(3100) - (forgoneInterest) ;
// reconciliation vs CEO
const ceoRecon = -410000 - 32000 - 3100 + total;
// provisionance check of Halvorsen's quoted numbers
const halvorsenQuoted = 340000 + 112000 + 410000;
const ceoSheetCheck = 7 * 0.25 * 64000;
const pct = (n) => (n * 100).toFixed(2);
const f = (n) => n.toLocaleString("en-US", {minimumFractionDigits: 2, maximumFractionDigits: 2});
console.log(`Day counts OK (expect 178/147/117/86/55): ${JSON.stringify(daycounts())}`);
console.log(`J-4411 int  = 68400×1%×178/30 = ${f(i4411)}`);
console.log(`J-4452 int  = 71250×1%×147/30 = ${f(i4452)}`);
console.log(`J-4490 int  = 66100×1%×117/30 = ${f(i4490)}`);
console.log(`J-4533R int = 71700×1%×86/30  = ${f(i4533R)}  (orig J-4533 @74800: ${f(i4533_orig)}, forgo ${f(forgoneInterest)})`);
console.log(`J-4571 int  = 59450×1%×55/30  = ${f(i4571)}`);
console.log(`Four-invoice interest = ${f(four)}; subtotal = ${f(fourInv)} + ${f(four)} = ${f(fourInv + four)}`);
console.log(`J-4533R = ${f(j4533R)}; + int = ${f(j4533R + i4533R)}`);
console.log(`Conversions = 5×25%×64,000 = ${f(conversions)}`);
console.log(`Principal total = ${f(principal)}; Interest total = ${f(total)}; Demand = ${f(grand)}`);
console.log(`Δ vs session 1 (${f(session1Total)}) = -${f(delta)} = -3,100 - ${f(forgoneInterest)} ✔ ${Math.abs(forgoneInterest + 3100 - delta) < 0.01 ? "reconciles" : "MISMATCH"}`);
console.log(`Δ vs CEO $862,000 = -${f(vsCEO)}; check -410000-32000-3100+${f(total)} = ${f(ceoRecon)} ${Math.abs(ceoRecon - -vsCEO) < 0.01 ? "✔ reconciles" : "MISMATCH"}`);
console.log(`Daily accruing: all interest-bearing ${(fourInv+j4533R).toLocaleString()} → ${f(dailyAll)}/day; four invoices only ${fourInv.toLocaleString()} → ${f(dailyFour)}/day`);
console.log(`Halvorsen quoted demand 340,000+112,000+410,000 = ${f(halvorsenQuoted)}; CEO sheet = $862,000 → match: ${halvorsenQuoted === 862000}`);
console.log(`Halvorsen's "$112,000, seven hires" vs CEO sheet 7×25%×64,000 = ${f(ceoSheetCheck)} → match: ${ceoSheetCheck === 112000}`);
console.log(`Sept 29 → Oct 25 = ${daysBetween("2026-09-29","2026-10-25")} days — letter predates our demand`);

